//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as GitHub Actions workflow commands
//! (`::error::`, `::warning::`, `::notice::`) for inline PR annotations.
//!
//! # Format
//!
//! Each diagnostic produces a single workflow command line:
//!
//! ```text
//! ::error file=config.yml,line=10,col=5,title=rule-id::Error message
//! ```
//!
//! GitHub Actions renders these as inline annotations on pull request diffs.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Produces `::error::`, `::warning::`, and `::notice::` annotations
/// that GitHub Actions renders as inline comments on pull requests.
pub struct GhaFormatter;

impl GhaFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn severity_to_command(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl Default for GhaFormatter {
    fn default() -> Self {
        Self::new()
    }
}

/// Escape a string for use in a GitHub Actions workflow command message.
fn escape_message(s: &str) -> String {
    s.replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
}

impl LintFormatter for GhaFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let command = Self::severity_to_command(diag.severity);

            // Build parameters
            let mut params = Vec::new();

            if let Some(ref span) = diag.span {
                params.push(format!("file={}", span.file.display()));
                params.push(format!("line={}", span.start_line));

                if span.end_line != span.start_line {
                    params.push(format!("endLine={}", span.end_line));
                }

                if span.start_col > 1 {
                    params.push(format!("col={}", span.start_col));
                }

                if span.end_col != usize::MAX && span.end_col != span.start_col {
                    params.push(format!("endColumn={}", span.end_col));
                }
            }

            params.push(format!("title={}", diag.rule_id.0));

            let params_str = params.join(",");

            // Build message body
            let mut message = escape_message(&diag.message);

            if let Some(ref suggestion) = diag.suggestion {
                message.push_str(&format!("%0Asuggestion: {}", escape_message(suggestion)));
            }

            for related in &diag.related {
                message.push_str(&format!(
                    "%0Anote: {} ({}:{})",
                    escape_message(&related.message),
                    related.span.file.display(),
                    related.span.start_line
                ));
            }

            writeln!(writer, "::{command} {params_str}::{message}")?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
