        assert!(output.contains("title=circular-dependency"));
    }

    #[test]
    fn includes_suggestion_in_message() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test"),
            Severity::Warning,
