        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("100%25 fail%0Aline two%0Dend"));
    }

    #[test]
    fn empty_diagnostics_produces_no_output() {
        let formatter = GhaFormatter::new();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();

        assert!(output.is_empty());
    }

    #[test]
    fn default_impl_works() {
        let formatter = GhaFormatter::default();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test"),
            Severity::Error,
            "msg",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("::error"));
    }

    #[test]
    fn multiple_diagnostics_produce_multiple_lines() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "first"),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "second"),
            LintDiagnostic::new(RuleId::new("r3"), Severity::Hint, "third"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        let lines: Vec<&str> = output.lines().collect();
        assert_eq!(lines.len(), 3);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
        assert!(lines[2].starts_with("::notice "));
    }

    #[test]
    fn includes_end_column_when_meaningful() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::new("config.yml", 10, 5, 10, 20)),
