//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as GitHub Actions workflow commands
//! (`::error::`, `::warning::`, `::notice::`) for inline PR annotations.
//!
//! # Format
//!
//! Each diagnostic produces a single workflow command line:
//!
//! ```text
//! ::error file=config.yml,line=10,col=5,title=rule-id::Error message
//! ```
//!
//! GitHub Actions renders these as inline annotations on pull request diffs.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Produces `::error::`, `::warning::`, and `::notice::` annotations
/// that GitHub Actions renders as inline comments on pull requests.
pub struct GhaFormatter;

impl GhaFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn severity_to_command(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl Default for GhaFormatter {
    fn default() -> Self {
        Self::new()
    }
}

/// Escape a string for use in a GitHub Actions workflow command message.
fn escape_message(s: &str) -> String {
    s.replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
}

impl LintFormatter for GhaFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let command = Self::severity_to_command(diag.severity);

            // Build parameters
            let mut params = Vec::new();

            if let Some(ref span) = diag.span {
                params.push(format!("file={}", span.file.display()));
                params.push(format!("line={}", span.start_line));

                if span.end_line != span.start_line {
                    params.push(format!("endLine={}", span.end_line));
                }

                if span.start_col > 1 {
                    params.push(format!("col={}", span.start_col));
                }

                if span.end_col != usize::MAX && span.end_col != span.start_col {
                    params.push(format!("endColumn={}", span.end_col));
                }
            }

            params.push(format!("title={}", diag.rule_id.0));

            let params_str = params.join(",");

            // Build message body
            let mut message = escape_message(&diag.message);

            if let Some(ref suggestion) = diag.suggestion {
                message.push_str(&format!("%0Asuggestion: {}", escape_message(suggestion)));
            }

            for related in &diag.related {
                message.push_str(&format!(
                    "%0Anote: {} ({}:{})",
                    escape_message(&related.message),
                    related.span.file.display(),
                    related.span.start_line
                ));
            }

            writeln!(writer, "::{command} {params_str}::{message}")?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_as_error_command() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Error,
            "Something went wrong",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::error "));
        assert!(output.contains("::Something went wrong"));
    }

    #[test]
    fn formats_warning_as_warning_command() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Warning,
            "Be careful",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::warning "));
    }

    #[test]
    fn formats_hint_as_notice_command() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Hint,
            "Consider this",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::notice "));
    }

    #[test]
    fn includes_file_and_line_when_span_present() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::line("config.yml", 15)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("file=config.yml"));
        assert!(output.contains("line=15"));
    }

    #[test]
    fn omits_location_when_no_span() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test"),
            Severity::Error,
            "msg",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("file="));
        assert!(!output.contains("line="));
    }

    #[test]
    fn includes_col_when_greater_than_one() {
        let formatter = GhaFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                    .with_span(Span::new("config.yml", 10, 5, 10, 20)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("col=5"));
    }

    #[test]
    fn omits_col_one() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::line("config.yml", 10)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        // Should not contain col= since start_col is 1
        assert!(!output.contains("col="));
    }

    #[test]
    fn includes_end_line_when_different() {
        let formatter = GhaFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                    .with_span(Span::new("config.yml", 10, 1, 15, 1)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("endLine=15"));
    }

    #[test]
    fn omits_end_line_when_same() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::line("config.yml", 10)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("endLine="));
    }

    #[test]
    fn includes_rule_id_as_title() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "msg",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("title=circular-dependency"));
    }

    #[test]
    fn includes_suggestion_in_message() {
        let formatter = GhaFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Warning, "Problem found")
                    .with_suggestion("Try this fix"),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("Problem found%0Asuggestion: Try this fix"));
    }

    #[test]
    fn includes_related_info_in_message() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Circular dependency",
        )
        .with_related(Span::line("config.yml", 5), "step_a defined here")];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("%0Anote: step_a defined here (config.yml:5)"));
    }

    #[test]
    fn escapes_special_characters() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test"),
            Severity::Error,
            "100% fail\nline two\rend",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("100%25 fail%0Aline two%0Dend"));
    }

    #[test]
    fn empty_diagnostics_produces_no_output() {
        let formatter = GhaFormatter::new();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();

        assert!(output.is_empty());
    }

    #[test]
    fn default_impl_works() {
        let formatter = GhaFormatter::default();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test"),
            Severity::Error,
            "msg",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("::error"));
    }

    #[test]
    fn multiple_diagnostics_produce_multiple_lines() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "first"),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "second"),
            LintDiagnostic::new(RuleId::new("r3"), Severity::Hint, "third"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        let lines: Vec<&str> = output.lines().collect();
        assert_eq!(lines.len(), 3);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
        assert!(lines[2].starts_with("::notice "));
    }

    #[test]
    fn includes_end_column_when_meaningful() {
        let formatter = GhaFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                    .with_span(Span::new("config.yml", 10, 5, 10, 20)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("endColumn=20"));
    }

    #[test]
    fn omits_end_column_when_max() {
        let formatter = GhaFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::line("config.yml", 10)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("endColumn="));
    }
}
